#define main display_program_main
#include "../udp_rk_rk_yolo/S/x11/csrc/main.cpp"
#undef main
#include <cassert>
#include <vector>
static SharedMemoryControl* control(SharedMemoryManager&m){return m.type==SHM_TYPE_PCIE?&m.shm_ptr.pcie_ptr->control:&m.shm_ptr.udp_ptr->control;}
static void retired_writer(SharedMemoryManager&m){shmdt(m.shm_ptr.generic_ptr);sem_close(m.write_sem);sem_close(m.read_sem);memset(&m,0,sizeof m);}
static void source_test(SharedMemoryType type){SharedMemoryManager reader={},writer={},replacement={};int available=0;uint64_t checked=0;uint32_t cursor=99;assert(!maintain_live_source(&reader,type,&available,&checked,&cursor)&&!available);assert(!shared_memory_init(&writer,type,1));std::vector<uint16_t>data(640*480,0x1234),output(640*480);assert(!shared_memory_write_image(&writer,(uint8_t*)data.data(),640,480));assert(!maintain_live_source(&reader,type,&available,&checked,&cursor)&&!available);checked=0;assert(maintain_live_source(&reader,type,&available,&checked,&cursor)&&available&&cursor==0);uint32_t id=0,w=0,h=0;assert(shared_memory_read_image(&reader,(uint8_t*)output.data(),output.size()*2,&w,&h,&id)>0&&id==1&&output==data);cursor=id;assert(!shared_memory_read_image(&reader,(uint8_t*)output.data(),output.size()*2,&w,&h,&id));control(writer)->writer_active=0;checked=0;assert(!maintain_live_source(&reader,type,&available,&checked,&cursor)&&!available);assert(shmget(type==SHM_TYPE_PCIE?SHM_PCIE_IMAGE_KEY:SHM_UDP_IMAGE_KEY,0,0)==writer.shm_id);control(writer)->writer_active=1;checked=0;assert(maintain_live_source(&reader,type,&available,&checked,&cursor)&&cursor==0);assert(shared_memory_read_image(&reader,(uint8_t*)output.data(),output.size()*2,&w,&h,&id)>0&&id==1);cursor=id;int old_id=reader.shm_id;assert(!shared_memory_init(&replacement,type,1));std::fill(data.begin(),data.end(),0xabcd);assert(!shared_memory_write_image(&replacement,(uint8_t*)data.data(),640,480));checked=0;assert(maintain_live_source(&reader,type,&available,&checked,&cursor)&&cursor==0&&reader.shm_id!=old_id);assert(!sem_wait(replacement.write_sem));assert(!shared_memory_read_image(&reader,(uint8_t*)output.data(),output.size()*2,&w,&h,&id));sem_post(replacement.write_sem);assert(shared_memory_read_image(&reader,(uint8_t*)output.data(),output.size()*2,&w,&h,&id)>0&&id==1&&output==data);retired_writer(writer);shared_memory_cleanup(&replacement);checked=0;assert(!maintain_live_source(&reader,type,&available,&checked,&cursor)&&!available);puts(type==SHM_TYPE_PCIE?"PCIE_REATTACH_GENERATION_SEMAPHORE_PASS":"UDP_REATTACH_GENERATION_SEMAPHORE_PASS");}
static void events_test(){start_fullscreen=0;RenderEngine e={};assert(!render_engine_init(&e));XSync(e.display,False);usleep(50000);assert(!render_engine_check_exit_event(&e));int width=e.window_width,height=e.window_height;Window helper=XCreateSimpleWindow(e.display,DefaultRootWindow(e.display),0,0,7,13,0,0,0);for(int n=0;n<2;++n){XEvent event={};event.xconfigure.type=ConfigureNotify;event.xconfigure.display=e.display;event.xconfigure.event=n?e.window:helper;event.xconfigure.window=helper;event.xconfigure.width=7;event.xconfigure.height=13;XSendEvent(e.display,e.window,False,StructureNotifyMask,&event);}XEvent destroy={};destroy.xdestroywindow.type=DestroyNotify;destroy.xdestroywindow.display=e.display;destroy.xdestroywindow.event=e.window;destroy.xdestroywindow.window=helper;XSendEvent(e.display,e.window,False,StructureNotifyMask,&destroy);XEvent key={};key.xkey.type=KeyPress;key.xkey.display=e.display;key.xkey.window=helper;key.xkey.keycode=XKeysymToKeycode(e.display,XK_q);XSendEvent(e.display,e.window,False,KeyPressMask,&key);XSync(e.display,False);assert(!render_engine_check_exit_event(&e));assert(width==e.window_width&&height==e.window_height);XResizeWindow(e.display,e.window,400,300);XSync(e.display,False);usleep(50000);assert(!render_engine_check_exit_event(&e));XWindowAttributes at={};XGetWindowAttributes(e.display,e.window,&at);assert(e.window_width==at.width&&e.window_height==at.height);XDestroyWindow(e.display,helper);render_engine_cleanup(&e);puts("HELPER_WINDOW_EVENTS_IGNORED_REAL_RESIZE_PASS");}
int main(int argc,char**argv){if(argc>1){SharedMemoryManager p={},u={};assert(!shared_memory_init(&p,SHM_TYPE_PCIE,1));assert(!shared_memory_init(&u,SHM_TYPE_UDP,1));std::vector<uint16_t>a(640*480,(uint16_t)strtoul(argv[1],nullptr,16)),b(640*480,(uint16_t)strtoul(argv[2],nullptr,16));for(int n=0;n<atoi(argv[3]);++n){assert(!shared_memory_write_image(&p,(uint8_t*)a.data(),640,480));assert(!shared_memory_write_image(&u,(uint8_t*)b.data(),640,480));usleep(50000);}shared_memory_cleanup(&p);shared_memory_cleanup(&u);return 0;}source_test(SHM_TYPE_PCIE);source_test(SHM_TYPE_UDP);events_test();}
